// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new C();

        DummyPriceFeed feed = new DummyPriceFeed();
        DummyToken collateral = new DummyToken();
        DummyToken borrow = new DummyToken();

        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0xFEE)
        });
        InitializeRiskConfigParams memory r = InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.2e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1 days,
            maxTenor: 365 days
        });
        InitializeOracleParams memory o = InitializeOracleParams({
            priceFeed: address(feed),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(0xWETH),
            underlyingCollateralToken: address(collateral),
            underlyingBorrowToken: address(borrow),
            variablePool: address(0xP001)
        });

        vm.prank(owner);
        c.initialize(owner, f, r, o, d);
    }

    function testFuzz_property(bytes[] memory data) public {
        // Admin pauses the protocol; in the reference the stored paused state becomes true.
        vm.prank(owner);
        c.pause();

        // Any multicall batch, no matter its contents, must be rejected while paused
        // because c.multicall is gated by whenNotPaused.
        vm.prank(owner);
        bool ok;
        try c.multicall(data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: while the protocol is paused, every multicall attempt reverts.
        // Reference: always ok == false. Mutant (paused() always false): batches such as
        // an empty one pass the gate and complete, so ok == true for some input.
        assertTrue(!ok);
    }
}

contract DummyPriceFeed {
    function getPrice() external pure returns (uint256) {
        return 1e18;
    }
}

contract DummyToken {
    function decimals() external pure returns (uint8) {
        return 18;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();

        FakePriceFeed priceFeed = new FakePriceFeed();
        FakeToken collateralToken = new FakeToken();
        FakeToken borrowToken = new FakeToken();

        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(this)
        });
        InitializeRiskConfigParams memory r = InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.2e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 365 days
        });
        InitializeOracleParams memory o = InitializeOracleParams({
            priceFeed: address(priceFeed),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(this),
            underlyingCollateralToken: address(collateralToken),
            underlyingBorrowToken: address(borrowToken),
            variablePool: address(this)
        });

        c.initialize(address(this), f, r, o, d);
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // grant the fuzzed actor the PAUSER_ROLE (admin is address(this))
        vm.prank(address(this));
        c.grantRole(0x00, actor);

        // authorized actor pauses the protocol
        vm.prank(actor);
        try c.pause() {
            // expected in the reference
        } catch {
            // would violate the rule, but cannot happen in either version
        }

        // general rule: the same authorized actor can complete the pause -> unpause cycle
        bool unpausedOk;
        vm.prank(actor);
        try c.unpause() {
            unpausedOk = true;
        } catch {
            unpausedOk = false;
        }

        assertTrue(unpausedOk);
    }
}

contract FakePriceFeed {
    function getPrice() external pure returns (uint256) {
        return 1e18;
    }

    function decimals() external pure returns (uint8) {
        return 18;
    }
}

contract FakeToken {
    function name() external pure returns (string memory) {
        return "T";
    }

    function symbol() external pure returns (string memory) {
        return "T";
    }

    function decimals() external pure returns (uint8) {
        return 18;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new C();
        // initialize with owner so roles can be granted
        C.InitializeFeeConfigParams memory f = C.InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0xFEE)
        });
        C.InitializeRiskConfigParams memory r = C.InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.1e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 365 days
        });
        C.InitializeOracleParams memory o = C.InitializeOracleParams({
            priceFeed: address(0x0F),
            variablePoolBorrowRateStaleRateInterval: 0
        });
        C.InitializeDataParams memory d = C.InitializeDataParams({
            weth: address(0xW),
            underlyingCollateralToken: address(0xC),
            underlyingBorrowToken: address(0xB),
            variablePool: address(0xP)
        });
        vm.prank(owner);
        c.initialize(owner, f, r, o, d);
    }

    function testFuzz_property(address pauser) public {
        vm.assume(pauser != address(0));
        // any PAUSER_ROLE holder is admissible
        vm.prank(owner);
        c.grantRole(c.PAUSER_ROLE(), pauser);

        // first pause must succeed for an authorized pauser
        vm.prank(pauser);
        c.pause();

        // general rule: with the stored paused state now true, a second pause()
        // must revert (EnforcedPause), regardless of which holder calls it
        bool secondPauseSucceeded;
        vm.prank(pauser);
        try c.pause() {
            secondPauseSucceeded = true;
        } catch {
            secondPauseSucceeded = false;
        }

        assertTrue(!secondPauseSucceeded);
    }
}
